P10_1_64BIT_REGISTER_PAIRS = {
    'P10_1_TOTAL_BYTES': (0x918, 0x91C),
    'P10_1_TIMER_SNAPSHOT': (0x93C, 0x940),
    'P10_1_APPLICATION_ACCEPTED': (0x944, 0x948),
    'P10_1_APPLICATION_COMMITTED': (0x94C, 0x950),
    'P10_1_FRAME_ACKED': (0x954, 0x958),
    'P10_1_WIRE_BYTES': (0x95C, 0x960),
    'P10_1_DMA_STALL': (0x96C, 0x970),
    'P10_1_AXIS_STALL': (0x974, 0x978),
    'P10_1_ACK_WAIT': (0x980, 0x984),
    'P10_1_DIRECTION_QUIET': (0x988, 0x98C),
    'P10_1_PS_PREPARE': (0x990, 0x994),
    'P10_1_CRC_SHA': (0x998, 0x99C),
}

def read_p10_1_snapshot_u64(read32, name):
    low_offset, high_offset = P10_1_64BIT_REGISTER_PAIRS[name]
    for _ in range(4):
        before = read32(IR_REG_P10_1_SNAPSHOT_GENERATION)
        if before & 1:
            continue
        low = read32(low_offset)
        high = read32(high_offset)
        after = read32(IR_REG_P10_1_SNAPSHOT_GENERATION)
        if before == after and not (after & 1):
            return (high << 32) | low
    raise RuntimeError('unstable P10.1 counter snapshot')
